<?php
$ready=packageRows("p.status_paket IN ('Tersimpan','Siap Kirim')");
$shipping=rows('SELECT g.*,p.nama_penerima,p.kota_tujuan,p.berat_kg,t.nama_petugas FROM pengiriman g JOIN paket p USING(no_resi) JOIN petugas t USING(id_petugas) ORDER BY waktu_kirim DESC,id_pengiriman DESC');
$readyCount=count(array_filter($ready,fn($p)=>$p['status_paket']==='Siap Kirim'));
heading('','Pengiriman','Tandai paket siap kirim, catat pengiriman, lalu konfirmasi saat tiba.',modalButton('Catat pengiriman','kirim-form','truck'));
stats([['Siap diberangkatkan',num($readyCount),'Paket sudah berstatus Siap Kirim','box','orange'],['Dalam perjalanan',num(count(array_filter($shipping,fn($g)=>$g['status_kirim']==='Dalam Perjalanan'))),'Sedang dibawa oleh kurir','truck','blue'],['Tiba di tujuan',num(count(array_filter($shipping,fn($g)=>in_array($g['status_kirim'],['Terkirim','Selesai'])))),'Pengiriman selesai','check','green'],['Total pengiriman',num(count($shipping)),'Seluruh riwayat outbound','out','purple']]);
?>
<section class="panel section-gap"><div class="panel-head"><div><h2>Persiapan pengiriman</h2><p>Tandai siap kirim sebelum menyerahkan paket ke kurir</p></div><span class="count-pill"><?=count($ready)?> paket</span></div><?php if(!$ready):emptyState('Tidak ada paket dalam antrean');else:?><div class="table-wrap"><table><thead><tr><th>Nomor resi</th><th>Penerima & tujuan</th><th>Lokasi</th><th>Status paket</th><th>Tindakan</th></tr></thead><tbody><?php foreach($ready as $p):?><tr><td><a class="resi" href="<?=e(url('paket',['resi'=>$p['no_resi']]))?>"><?=icon('box')?><?=e($p['no_resi'])?></a></td><td><strong class="cell-title"><?=e($p['nama_penerima'])?></strong><span class="cell-sub"><?=e($p['kota_tujuan'])?></span></td><td><?=e($p['lokasi']?:'—')?></td><td><?=badge($p['status_paket'])?></td><td><?=$p['status_paket']==='Tersimpan'?actionForm('siap','outbound',['no_resi'=>$p['no_resi']],'Siap kirim'):linkButton('Kirim paket',url('outbound',['resi'=>$p['no_resi'],'open'=>'kirim-form']),'truck','secondary small')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<section class="panel"><div class="panel-head"><div><h2>Riwayat pengiriman</h2><p>Pelacakan serah terima dan kedatangan paket</p></div></div><?php if(!$shipping):emptyState('Belum ada pengiriman');else:?><div class="table-wrap"><table><thead><tr><th>Paket & tujuan</th><th>Kurir & kendaraan</th><th>Petugas</th><th>Keberangkatan</th><th>Status pengiriman</th><th>Tindakan</th></tr></thead><tbody><?php foreach($shipping as $g):?><tr><td><a class="resi" href="<?=e(url('paket',['resi'=>$g['no_resi']]))?>"><?=e($g['no_resi'])?></a><span class="cell-sub"><?=e($g['kota_tujuan'])?></span></td><td><strong class="cell-title"><?=e($g['nama_kurir'])?></strong><span class="cell-sub"><?=e($g['no_kendaraan'])?></span></td><td><?=e($g['nama_petugas'])?></td><td class="muted"><?=e(stamp($g['waktu_kirim']))?></td><td><?=badge($g['status_kirim'],true)?></td><td><?=$g['status_kirim']==='Dalam Perjalanan'?actionForm('tiba','outbound',['no_resi'=>$g['no_resi']],'Tandai tiba','check',true):'<span class="muted">Selesai</span>'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php
beginDialog('kirim-form','Catat pengiriman','Serahkan paket siap kirim kepada kurir.','kirim','outbound');$options=[];foreach($ready as $p)if($p['status_paket']==='Siap Kirim')$options[$p['no_resi']]=$p['no_resi'].' · '.$p['nama_penerima'].' · '.$p['kota_tujuan'];
selectField('no_resi','Paket siap kirim',$options,param('resi'));selectField('id_petugas','Petugas pengiriman',staffOptions('Outbound Sorter'));field('nama_kurir','Nama kurir');field('no_kendaraan','Nomor kendaraan','','text',true,20,'placeholder="KB 1234 AB"');field('waktu_kirim','Waktu keberangkatan',date('Y-m-d\TH:i'),'datetime-local');echo '<div class="form-hint">'.icon('truck').'<span>Penempatan ditutup dan kapasitas rak dikurangi otomatis saat pengiriman disimpan.</span></div>';endDialog('Simpan pengiriman');
?>
